const observed = 'observed'
const inference = 'inference'
const recommendation = 'recommendation'
const unknown = 'unknown'

const S = (path, start, end, label) => ({ path, start, end, label })

const explain = (title, thesis, facts, meaning, consequence, refs = [], status = observed, external = []) => ({
  kind: 'explain', title, thesis, facts, meaning, consequence, refs, status, external,
})

const code = (title, thesis, source, focus, mechanism, decision, risk, refs = [], status = observed, external = []) => ({
  kind: 'code', title, thesis, source, focus, mechanism, decision, risk, refs, status, external,
})

const decisiveAlgorithmEvidence = {
  A07: S('src/utils/processUserInput/processUserInput.ts', 515, 588, 'bash·slash·normal prompt의 결정적 dispatch'),
  A13: S('src/services/compact/compact.ts', 596, 742, 'boundary·summary message·post-compact 결과 구성'),
  A22: S('src/tools/FileReadTool/FileReadTool.ts', 1020, 1040, 'range read와 readFileState observation 기록'),
  A23: S('src/tools/FileEditTool/FileEditTool.ts', 427, 491, 'await를 앞당긴 뒤 stale check→patch→동기 write'),
  A30: S('src/tools/AgentTool/runAgent.ts', 500, 770, 'child controller·context·transcript·query 합류'),
  A33: S('src/services/plugins/PluginInstallationManager.ts', 60, 120, 'diff→pending state→reconcile progress'),
}

const algorithm = ({ id, title, thesis, source, problem, inputs, state, steps, invariants, complexity, decision, failures, improvement, theory = [], refs = [], status = observed }) => ({
  kind: 'algorithm', id, title, thesis, source: decisiveAlgorithmEvidence[id] ?? source, problem, inputs, state, steps, invariants, complexity, decision, failures, improvement, theory, refs, status,
})

const matrix = (title, thesis, columns, rows, reading, refs = [], status = observed) => ({
  kind: 'matrix', title, thesis, columns, rows, reading, refs, status,
})

const walkthrough = (title, thesis, stages, invariant, failure, refs = [], status = observed) => ({
  kind: 'walkthrough', title, thesis, stages, invariant, failure, refs, status,
})

const mechanismStudy = config => ({ kind: 'mechanism-study', status: observed, ...config })

const chapter = (title, thesis, paths, pages) => ({ title, thesis, paths, pages })

